// ResutoPay: checkout, splits, refunds, reconciliation.
// Owner: Agent D1 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { idempotencyKey, isoDate, isoDateTime, optionalText, positiveMinor, text, uuid } from './common';

export const paymentsContractsVersion = 2 as const;

export const PAYMENT_METHODS = ['cash', 'card', 'wallet', 'instapay', 'cod', 'deposit_credit', 'bank_transfer', 'test'] as const;
export const paymentMethod = z.enum(PAYMENT_METHODS);
export type PaymentMethodKey = (typeof PAYMENT_METHODS)[number];

/** Methods a guest can complete online through a provider redirect. */
export const ONLINE_METHODS = ['card', 'wallet'] as const satisfies readonly PaymentMethodKey[];
/** Methods settled in person and confirmed by staff (never by the guest). */
export const OFFLINE_METHODS = ['cash', 'cod', 'instapay', 'bank_transfer'] as const satisfies readonly PaymentMethodKey[];
export const isOnlineMethod = (m: string) => (ONLINE_METHODS as readonly string[]).includes(m);

export const PAYMENT_PROVIDERS = ['simulated', 'paymob', 'stripe', 'moyasar'] as const;
export const paymentProvider = z.enum(PAYMENT_PROVIDERS);
export type PaymentProviderKey = (typeof PAYMENT_PROVIDERS)[number];

export const CHECKOUT_PURPOSES = ['order', 'visit_bill', 'bill_share', 'reservation_deposit', 'payment_link'] as const;
export const checkoutPurpose = z.enum(CHECKOUT_PURPOSES);
export type CheckoutPurpose = (typeof CHECKOUT_PURPOSES)[number];
export const checkoutChannel = z.enum(['web', 'qr', 'whatsapp', 'staff', 'mcp']);

export { apportion, planSplit, SplitRuleError, type BillUnit, type SplitPlan } from './split';

// ---------------------------------------------------------------------------
// Request schemas
// ---------------------------------------------------------------------------

export const startCheckout = z.object({
  method: paymentMethod.refine((m) => m !== 'deposit_credit' && m !== 'test', 'Choose a payment method'),
  payerName: optionalText(60),
});
export type StartCheckout = z.infer<typeof startCheckout>;

export const sandboxComplete = z.object({ outcome: z.enum(['success', 'failure']) });

export const visitCheckout = z.object({ amountMinor: positiveMinor.optional(), key: idempotencyKey });

const unitRef = z.object({ lineId: uuid, unit: z.number().int().min(0).max(98) });
export const createSplit = z.object({
  mode: z.enum(['whole', 'equal', 'custom', 'items']),
  people: z.number().int().min(2).max(20).optional(),
  amounts: z.array(positiveMinor).min(2).max(20).optional(),
  allocations: z.array(z.object({ label: optionalText(60), items: z.array(unitRef).min(1).max(200) })).min(2).max(20).optional(),
  labels: z.array(z.string().trim().max(60)).max(20).optional(),
  key: idempotencyKey,
});
export type CreateSplit = z.infer<typeof createSplit>;

export const shareCheckout = z.object({ payerName: optionalText(60), key: idempotencyKey });

export const reservationCheckout = z.object({ token: z.string().min(16).max(200) });

export const collectPayment = z.object({
  orderId: uuid.optional(),
  visitId: uuid.optional(),
  shareId: uuid.optional(),
  method: z.enum(['cash', 'cod', 'instapay', 'bank_transfer', 'card']),
  amountMinor: positiveMinor,
  reference: optionalText(120),
  driverId: uuid.optional(),
  note: optionalText(300),
  key: idempotencyKey,
}).refine((b) => !!(b.orderId || b.visitId || b.shareId), { message: 'Choose an order, table bill or share', path: ['orderId'] })
  .refine((b) => !['instapay', 'bank_transfer', 'card'].includes(b.method) || !!b.reference, { message: 'Enter the transfer or terminal reference', path: ['reference'] });
export type CollectPayment = z.infer<typeof collectPayment>;

export const createPaymentLink = z.object({
  orderId: uuid.optional(),
  visitId: uuid.optional(),
  amountMinor: positiveMinor.optional(),
  allowedMethods: z.array(paymentMethod).min(1).max(6).optional(),
  description: optionalText(200),
  expiresInMinutes: z.number().int().min(5).max(7 * 24 * 60).optional(),
  key: idempotencyKey,
}).refine((b) => !!(b.orderId || b.visitId), { message: 'Choose an order or table bill', path: ['orderId'] });
export type CreatePaymentLink = z.infer<typeof createPaymentLink>;

export const createRefund = z.object({ amountMinor: positiveMinor, reason: text(300), key: idempotencyKey });
export type CreateRefund = z.infer<typeof createRefund>;

export const listPaymentsQuery = z.object({
  status: z.string().max(40).optional(),
  method: paymentMethod.optional(),
  provider: z.string().max(40).optional(),
  branchId: uuid.optional(),
  orderId: uuid.optional(),
  from: isoDate.optional(),
  to: isoDate.optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
  cursor: z.string().max(200).optional(),
});

export const reconciliationRunInput = z.object({
  provider: z.string().regex(/^[a-z0-9_]{2,40}$/),
  branchId: uuid.optional(),
  from: isoDateTime,
  to: isoDateTime,
  source: z.enum(['provider_api', 'statement_upload']),
  /** Settlement CSV (statement_upload): header row with transaction_id, amount (major units) or amount_minor, currency, status, fee/fee_minor. */
  csv: z.string().max(5_000_000).optional(),
}).refine((b) => b.source !== 'statement_upload' || !!b.csv, { message: 'Upload the settlement CSV', path: ['csv'] })
  .refine((b) => new Date(b.to) > new Date(b.from), { message: 'The period end must be after its start', path: ['to'] });
export type ReconciliationRunInput = z.infer<typeof reconciliationRunInput>;

export const cashCountInput = z.object({
  branchId: uuid,
  from: isoDateTime,
  to: isoDateTime,
  counts: z.array(z.object({
    method: z.enum(['cash', 'cod']),
    staffId: uuid.nullable().optional(),
    driverId: uuid.nullable().optional(),
    countedMinor: z.number().int().min(0).max(1e13),
  })).min(1).max(200),
  note: optionalText(300),
}).refine((b) => new Date(b.to) > new Date(b.from), { message: 'The period end must be after its start', path: ['to'] });
export type CashCountInput = z.infer<typeof cashCountInput>;

export const resolveReconciliationItem = z.object({ resolution: z.enum(['accepted', 'adjusted', 'escalated']), notes: optionalText(500) });

// ---------------------------------------------------------------------------
// Response shapes (camelCase)
// ---------------------------------------------------------------------------

export interface CheckoutMethodOption {
  method: PaymentMethodKey;
  kind: 'online' | 'offline';
  provider: string | null;
  sandbox: boolean;
  /** Offline methods: what the guest should do (pay at counter, to the driver, transfer details). */
  instructions?: string | null;
}

export interface CheckoutView {
  id: string;
  status: 'open' | 'processing' | 'paid' | 'expired' | 'cancelled';
  purpose: CheckoutPurpose;
  amountMinor: number;
  currency: string;
  description: string | null;
  merchant: { name: string; nameAr: string | null; branch: string | null; branchAr: string | null; country: string };
  items: Array<{ name: string; nameAr: string | null; quantity: number; totalMinor: number }>;
  methods: CheckoutMethodOption[];
  expiresAt: string;
  paidAt: string | null;
  attempt: null | { id: string; method: string; provider: string; status: string; redirectUrl: string | null; sandbox: boolean; failureReason: string | null };
  sandbox: boolean;
  returnUrl: string | null;
}

export interface StartCheckoutResult {
  kind: 'redirect' | 'offline' | 'paid';
  redirectUrl?: string;
  instructions?: string;
  sandbox: boolean;
  paymentId?: string;
}

export interface SplitShareView {
  id: string;
  label: string;
  amountMinor: number;
  paidMinor: number;
  status: 'open' | 'paid' | 'void';
  url: string;
  items: Array<{ lineId: string; unit: number; name: string; amountMinor: number }>;
}
export interface SplitView {
  id: string;
  mode: 'whole' | 'equal' | 'items' | 'custom';
  totalMinor: number;
  currency: string;
  status: 'open' | 'settled' | 'cancelled';
  createdAt: string;
  shares: SplitShareView[];
}

export interface ReceiptView {
  id: string;
  paymentId: string;
  status: 'paid' | 'partially_refunded' | 'refunded';
  at: string;
  currency: string;
  kind: 'bill' | 'share' | 'deposit' | 'order';
  restaurant: { name: string; nameAr: string | null };
  branch: { name: string; nameAr: string | null } | null;
  amountMinor: number;
  refundedMinor: number;
  payment: {
    provider: string; method: string; mode: 'test' | 'live'; transactionId: string;
    /** PAY-19: 'gateway' = confirmed by the payment provider's verified evidence; 'staff' = recorded by staff who received or checked it (cash, COD, transfer, terminal). */
    verification?: 'gateway' | 'staff';
  };
  reference: { orders: string[]; reservation?: string };
  table: string | null;
  items: Array<{ name: string; nameAr: string | null; unitPriceMinor: number; quantity: number; totalMinor: number }>;
  totals: { subtotalMinor: number; discountMinor: number; feeMinor: number; taxMinor: number; totalMinor: number; paidMinor: number; dueMinor: number; creditMinor: number };
  split: null | { yourShareMinor: number; participants: number; paidCount: number; mode: string; label: string };
  reservation: null | { code: string; startsAt: string; partySize: number; guestName: string };
}
